using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResource(Name = "config://app",
    Description = "Returns application configuration data",
    MimeType = "application/json")]
public class ConfigResource
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["appName"] = "McpHttpServer",
        ["version"] = "1.0.0",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["analytics"] = false,
        },
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30,
    };

    [McpServerResourceRead]
    public static string Read() =>
        JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool(Name = "greet"), Description("Greets a user by name")]
    public static string Greet([Description("The name to greet")] string name) =>
        $"Hello, {name}! Welcome to the MCP HTTP server.";

    [McpServerTool(Name = "echo"), Description("Echoes back the provided message")]
    public static string Echo([Description("The message to echo")] string message) =>
        $"Echo: {message}";
}

